-- Deployable spec (not executed in demo mode)
CREATE OR REPLACE TASK SDP_AKTIA.SNOWBOTS.T_CLOSE_SENTINEL
  WAREHOUSE = SDP_BOT_WH
  SCHEDULE = 'USING CRON 0 6 * * * Europe/Helsinki'
  CONFIG = '{"autonomy": 3}'
  WHEN SYSTEM$STREAM_HAS_DATA('SDP_AKTIA.PUBLIC.STR_GL_JOURNAL')
AS
  CALL SDP_AKTIA.SNOWBOTS.SP_RUN_BOT('close-sentinel');

-- step 1 · Actuals landed: October Oracle GL + DW
SELECT SYSTEM$STREAM_HAS_DATA('SDP_AKTIA.PUBLIC.STR_GL_JOURNAL') OR SYSTEM$STREAM_HAS_DATA('SDP_AKTIA.PUBLIC.STR_DW_BALANCES');
-- step 2 · Completeness DMFs per feed
SELECT feed, SNOWFLAKE.CORE.ROW_COUNT(...) AS rows_loaded, expected_rows,
       rows_loaded / expected_rows AS completeness
FROM SDP_AKTIA.SNOWBOTS.V_FEED_EXPECTATIONS WHERE period = '2026-10';
-- step 3 · Fallback: paged extract from Aktia DW replica
CALL SDP_AKTIA.SNOWBOTS.SP_BACKFILL_FROM_DW('ORACLE_GL', '2026-10', page_size => 250000);
-- step 4 · Reconcile: GL vs Focus NII + intercompany across 3 entities
CALL SDP_AKTIA.SNOWBOTS.SP_RECONCILE(period => '2026-10', tolerance_pct => 0.5);
-- step 5 · Guardrail: completeness ≥ 98% and TB difference = 0
SELECT MIN(completeness) >= 0.98 AND ABS(SUM(tb_diff)) = 0 FROM SDP_AKTIA.SNOWBOTS.V_CLOSE_STATUS WHERE period = '2026-10';
-- step 6 · Lock period 2026-10 (awaiting CFO approval)
CALL SDP_AKTIA.PUBLIC.SP_LOCK_PERIOD('2026-10', approved_by => :approver);

