-- Deployable spec (not executed in demo mode)
CREATE OR REPLACE TASK SDP_AKTIA.SNOWBOTS.T_DRIVER_REFRESH
  WAREHOUSE = SDP_BOT_WH
  SCHEDULE = 'USING CRON 0 6 * * * Europe/Helsinki'
  CONFIG = '{"autonomy": 4}'
AS
  CALL SDP_AKTIA.SNOWBOTS.SP_RUN_BOT('driver-refresh');

-- step 1 · Marketplace share refreshed
SELECT MAX(date) FROM RATES_MARKETPLACE.PUBLIC.EURIBOR_DAILY;
-- step 2 · Upsert rate and market drivers
MERGE INTO SDP_AKTIA.PUBLIC.DIM_RATE_DRIVER t USING (SELECT * FROM RATES_MARKETPLACE.PUBLIC.EURIBOR_DAILY WHERE date = CURRENT_DATE) s ON t.tenor = s.tenor ...;
-- step 3 · Guardrail: daily move ≤ 25bp / 3%
SELECT MAX(ABS(bp_change)) <= 25 AND MAX(ABS(pct_change)) <= 0.03 FROM SDP_AKTIA.SNOWBOTS.V_DRIVER_MOVES;
-- step 4 · Recalculate NII and AUM fees for Nov–Dec
CALL SDP_AKTIA.PUBLIC.SP_RECALC(scope => 'NII,FEES', from_period => '2026-11');
-- step 5 · One-line impact note
SELECT AI_COMPLETE('claude-sonnet-4-5', 'One sentence on: ' || :impact_json);

