-- Deployable spec (not executed in demo mode)
CREATE OR REPLACE TASK SDP_AKTIA.SNOWBOTS.T_SPEND_GUARDIAN
  WAREHOUSE = SDP_BOT_WH
  SCHEDULE = 'USING CRON 0 6 * * * Europe/Helsinki'
  CONFIG = '{"autonomy": 1}'
AS
  CALL SDP_AKTIA.SNOWBOTS.SP_RUN_BOT('spend-guardian');

-- step 1 · Over-budget suppliers and renewals due ≤ 90 days
SELECT supplier, SUM(amount_eur) FROM SDP_AKTIA.PUBLIC.AKTIA_BASWARE_INVOICES WHERE over_budget_driver AND period >= '2026-07' GROUP BY 1;
-- step 2 · Compare unit price vs benchmark
SELECT c.vendor, c.unit_price / b.p50 - 1 AS premium FROM ... JOIN SDP_AKTIA.SNOWBOTS.V_VENDOR_BENCHMARK b ...;
-- step 3 · Recommendations to Cost Control
INSERT INTO SDP_AKTIA.PUBLIC.FACT_NOTIFICATION ...;

-- Deployable spec (not executed in demo mode)
CREATE OR REPLACE TASK SDP_AKTIA.SNOWBOTS.T_HC_RECONCILER
  WAREHOUSE = SDP_BOT_WH
  SCHEDULE = 'USING CRON 0 6 * * * Europe/Helsinki'
  CONFIG = '{"autonomy": 2}'
AS
  CALL SDP_AKTIA.SNOWBOTS.SP_RUN_BOT('hc-reconciler');

-- step 1 · SuccessFactors vs plan by cost centre
SELECT cost_centre, sf_fte, plan_fte FROM SDP_AKTIA.SNOWBOTS.V_HC_RECON WHERE period = '2026-10';
-- step 2 · Age open positions > 60 days
SELECT * FROM SDP_AKTIA.PUBLIC.V_HEADCOUNT_SUMMARY WHERE DATEDIFF(day, opened, CURRENT_DATE) > 60;
-- step 3 · Draft vacancy-savings adjustment
CALL SDP_AKTIA.PUBLIC.SP_DRAFT_ADJUSTMENT('HC_VACANCY', '2026-11');

-- Deployable spec (not executed in demo mode)
CREATE OR REPLACE TASK SDP_AKTIA.SNOWBOTS.T_FOCUS_SYNC
  WAREHOUSE = SDP_BOT_WH
  SCHEDULE = 'USING CRON 0 6 * * * Europe/Helsinki'
  CONFIG = '{"autonomy": 2}'
AS
  CALL SDP_AKTIA.SNOWBOTS.SP_RUN_BOT('focus-sync');

-- step 1 · Load Focus balance and margin forecast
SELECT portfolio, month, balance_eur, ftp_margin FROM SDP_AKTIA.SNOWBOTS.V_FOCUS_FORECAST WHERE run_date = CURRENT_DATE;
-- step 2 · NII check: Focus vs GL actuals and plan
SELECT SUM(focus_nii) - SUM(plan_nii) AS diff FROM SDP_AKTIA.SNOWBOTS.V_NII_RECON WHERE month BETWEEN '2026-11' AND '2026-12';
-- step 3 · Prepare adjusted values for write-back to Focus (draft)
CALL SDP_AKTIA.SNOWBOTS.SP_DRAFT_FOCUS_EXPORT(version => 'RF10');
